package trinary

import (
	"errors"
	"math"
)

// ParseTrinary converts a trinary number, represented as a string of
// 0, 1, and 2 characters, to its decimal equivalent using first
// principles.
//
// Strings containing any character other than 0, 1, or 2 are invalid,
// as are strings whose value does not fit in an int64. For invalid
// input ParseTrinary returns 0 and a non-nil error.
func ParseTrinary(s string) (int64, error) {
	var value int64
	for i := 0; i < len(s); i++ {
		digit := s[i] - '0'
		if digit < 0 || digit > 2 {
			return 0, errors.New("invalid trinary: contains a non-trinary digit")
		}
		if value > (math.MaxInt64-digit)/3 {
			return 0, errors.New("invalid trinary: value overflows int64")
		}
		value = value*3 + int64(digit)
	}
	return value, nil
}

